+name: Toggle and Toolbar source acceptance
+
+on:
+  pull_request:
+  push:
+    branches: [main]
+  workflow_dispatch:
+
+permissions:
+  contents: read
+
+concurrency:
+  group: navigation-${{ github.event.pull_request.number || github.ref }}
+  cancel-in-progress: true
+
+jobs:
+  navigation-browser:
+    name: Toggle and Toolbar browser
+    runs-on: ubuntu-22.04
+    timeout-minutes: 20
+    steps:
+      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6.1.0
+        with:
+          ref: ${{ github.event.pull_request.head.sha || github.sha }}
+          persist-credentials: false
+      - uses: pnpm/action-setup@fc06bc1257f339d1d5d8b3a19a8cae5388b55320 # v4.4.0
+        with:
+          version: 12.6.0
+          run_install: false
+      - uses: actions/setup-node@249970729cb0ef3589644e2896645e5dc5ba9c38 # v6.5.0
+        with:
+          node-version: '24'
+          package-manager-cache: false
+      - name: Frozen workspace install
+        run: bash scripts/bootstrap.sh
+      - name: Build actual library and check isolated public package
+        run: |
+          pnpm --filter @sveltery/base build
+          bash scripts/check-navigation-package.sh
+      - name: Install official secured Chromium
+        run: pnpm exec playwright install --with-deps chromium
+      - name: Actual React 19.2.8 and native Svelte acceptance
+        env:
+          PLAYWRIGHT_JSON_OUTPUT_NAME: .checks/navigation/browser-results.json
+        run: |
+          set -o pipefail
+          mkdir -p .checks/navigation
+          pnpm exec playwright test tests/browser/navigation.spec.ts tests/browser/toggle.spec.ts tests/browser/separator.spec.ts --reporter=list,json | tee .checks/navigation/browser.log
+      - name: Preserve actual paired browser observations and traces
+        if: always()
+        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4.6.2
+        with:
+          name: navigation-browser-evidence
+          path: |
+            .checks/navigation/
+            test-results/navigation-*/
+            test-results/toggle-*/
+            test-results/separator-*/
+          if-no-files-found: warn
+          retention-days: 14
